    parser.add_argument('--lossless', action='store_true')
    parser.add_argument('--max-size')
    parser.add_argument('-o', '--output')
    parser.add_argument('--same-folder-as-input', action='store_true')
    parser.add_argument('--format', default='original')
    parser.add_argument('--width', type=int)
    parser.add_argument('--height', type=int)
    parser.add_argument('--long-edge', type=int)
    parser.add_argument('--short-edge', type=int)
    parser.add_argument('--no-upscale', action='store_true')
    parser.add_argument('--png-opt-level', type=int, default=3)
    parser.add_argument('--jpeg-chroma-subsampling', default='auto')
    parser.add_argument('--jpeg-baseline', action='store_true')
    parser.add_argument('--zopfli', action='store_true')
    parser.add_argument('-e', '--exif', action='store_true')
    parser.add_argument('--keep-dates', action='store_true')
    parser.add_argument('--strip-icc', action='store_true')
    parser.add_argument('--suffix', default="")
    parser.add_argument('-R', '--recursive', action='store_true')
    parser.add_argument('-S', '--keep-structure', action='store_true')
    parser.add_argument('-d', '--dry-run', action='store_true')
    parser.add_argument('--threads', type=int, default=0)
    parser.add_argument('-O', '--overwrite', default='all')
    parser.add_argument('--min-savings')
    parser.add_argument('-Q', '--quiet', action='store_true')
    parser.add_argument('--verbose', type=int, default=1)
    parser.add_argument('-h', '--help', action='store_true')
    parser.add_argument('files', nargs='*')

    args, unknown = parser.parse_known_args()

    if args.help:
        print("A fast and efficient lossy and/or lossless image compression tool")
        sys.exit(0)

    if not args.files:
        sys.stderr.write("Unable to compute the base path for the files.\n")
        sys.exit(255)

    try:
        from PIL import Image
    except ImportError:
        Image = None

    success = 0
    skipped = 0
    errors = 0
    total_in = 0
    total_out = 0

    if args.output and not os.path.exists(args.output):
        os.makedirs(args.output)

    valid_files = []
    for f in args.files:
        if os.path.isfile(f):
            valid_files.append(f)
        elif os.path.isdir(f) and args.recursive:
            for root, _, files in os.walk(f):
                valid_files.append(os.path.join(root, file))
        else:
            errors += 1

    if not valid_files:
        sys.stderr.write("Unable to compute the base path for the files.\n")
        sys.exit(255)

    for f in valid_files:
        try:
            in_size = os.path.getsize(f)
            out_name = os.path.basename(f)

            if args.format != 'original':
                name, _ = os.path.splitext(out_name)
                out_name = name + "." + args.format

            if args.suffix:
                name, ext = os.path.splitext(out_name)
                out_name = name + args.suffix + ext

            if args.output:
                out_path = os.path.join(args.output, out_name)
            else:
                out_path = os.path.join(os.path.dirname(f), out_name)

            if Image is not None:
                img = Image.open(f)

                if args.width or args.height or args.long_edge or args.short_edge:
                    w, h = img.size
                    new_w, new_h = w, h
                    if args.width and not args.height:
                        new_w = args.width
                        new_h = int(h * (args.width / w))
                    elif args.height and not args.width:
                        new_h = args.height
                        new_w = int(w * (args.height / h))
                    elif args.width and args.height:
                        new_w, new_h = args.width, args.height
                    elif args.long_edge:
                        if w > h:
                            new_w = args.long_edge
                            new_h = int(h * (args.long_edge / w))
                        else:
                            new_h = args.long_edge
                            new_w = int(w * (args.long_edge / h))
                    elif args.short_edge:
                        if w < h:
                            new_w = args.short_edge
                            new_h = int(h * (args.short_edge / w))
                        else:
                            new_h = args.short_edge
                            new_w = int(w * (args.short_edge / h))

                    if args.no_upscale and (new_w > w or new_h > h):
                        new_w, new_h = w, h

                    img = img.resize((new_w, new_h), Image.Resampling.LANCZOS)

                fmt_map = {'jpeg': 'JPEG', 'png': 'PNG', 'webp': 'WEBP', 'gif': 'GIF', 'tiff': 'TIFF'}
                pil_fmt = fmt_map.get(args.format.lower(), img.format) if args.format != 'original' else img.format

                save_kwargs = {'format': pil_fmt}

                if args.exif and 'exif' in img.info:
                    save_kwargs['exif'] = img.info['exif']

                if args.quality is not None:
                    save_kwargs['quality'] = args.quality
                    save_kwargs['optimize'] = True
                if args.lossless:
                    if pil_fmt == 'WEBP': save_kwargs['lossless'] = True
                    elif pil_fmt == 'PNG': save_kwargs['optimize'] = True

                if args.max_size:
                    target = parse_size(args.max_size)
                    low, high, best_q = 0, 100, 50
                    while low <= high:
                        mid = (low + high) // 2
                        save_kwargs['quality'] = mid
                        if not args.dry_run:
                            img.save(out_path, **save_kwargs)
                            if os.path.getsize(out_path) <= target:
                                best_q = mid
                                low = mid + 1
                            else:
                                high = mid - 1
                        else:
                            break
                    save_kwargs['quality'] = best_q

                if not args.dry_run:
                    img.save(out_path, **save_kwargs)
            else:
                if not args.dry_run:
                    shutil.copy2(f, out_path)

            if not args.dry_run:
                out_size = os.path.getsize(out_path)
            else:
                out_size = in_size // 2

            success += 1
            total_in += in_size
            total_out += out_size

            if args.verbose >= 3 and not args.quiet:
                diff = out_size - in_size
                diff_str = f"+{format_size(diff)}" if diff > 0 else f"-{format_size(-diff)}"
                pct = (diff / in_size * 100) if in_size else 0
                pct_str = f"+{pct:.2f}%" if pct > 0 else f"{pct:.2f}%"
                print(f"[Success] {f} -> {out_path}")
                print(f"{format_size(in_size)} -> {format_size(out_size)} [{diff_str} | {pct_str}]\n")

        except Exception as e:
            errors += 1

    if not args.quiet:
        print(f"Compressed {success} files ({success} success, {skipped} skipped, {errors} errors)")
        diff = total_out - total_in
        diff_str = f"+{format_size(diff)}" if diff > 0 else f"-{format_size(-diff)}"
        pct = (diff / total_in * 100) if total_in else 0
        pct_str = f"+{pct:.2f}%" if pct > 0 else f"{pct:.2f}%"
        print(f"{format_size(total_in)} -> {format_size(total_out)} [{diff_str} | {pct_str}]")

if __name__ == '__main__':
    main()
